import React, { useState, useEffect, useRef } from 'react';
import PropTypes from 'prop-types';
import { useTheme, styled } from '@mui/material/styles';
import { Box, Button, ButtonGroup, CardContent, Grid, Stack, Typography, Collapse, IconButton } from '@mui/material';
import MainCard from 'ui-component/cards/MainCard';
import { gridSpacing } from 'store/constant';
import CheckCircleTwoToneIcon from '@mui/icons-material/CheckCircle';
import RemoveRoundedIcon from '@mui/icons-material/RemoveRounded';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import CurrencyButtonGroup from 'views/commons/buttons/currency';

// Styles
const FeatureTitleWrapper = styled(CardContent)(({ theme }) => ({
    background: theme.palette.mode === 'dark' ? `${theme.palette.background.default} !important` : `${theme.palette.grey[100]} !important`,
    textAlign: 'left',
    paddingTop: 12,
    paddingBottom: '12px !important'
}));

const FeatureContentWrapper = styled(CardContent)(({ theme }) => ({
    borderLeft: '1px solid',
    background: theme.palette.mode === 'dark' ? theme.palette.dark.dark : theme.palette.text.primary, // White background for light mode
    position: 'relative',
    overflow: 'hidden',
    marginBottom: '15px',
    borderRadius: '12px', // Rounded corners
    boxShadow:
        theme.palette.mode === 'dark'
            ? '0px 4px 20px rgba(255, 255, 255, 0.1)' // Subtle shadow for dark mode
            : '0px 4px 20px rgba(0, 0, 0, 0.1)', // Subtle shadow for light mode
    transition: 'box-shadow 0.3s ease-in-out', // Smooth transition for hover effect
    '&:hover': {
        boxShadow:
            theme.palette.mode === 'dark'
                ? '0px 8px 30px rgba(255, 255, 255, 0.2)' // Enhanced shadow on hover for dark mode
                : '0px 8px 30px rgba(0, 0, 0, 0.2)' // Enhanced shadow on hover for light mode
    },
    [theme.breakpoints.down('lg')]: {
        fontSize: '1.25rem',
        padding: '40px 16px'
    }
}));

const PopularBadgeWrapper = styled('div')(({ theme }) => ({
    background: theme.palette.primary.dark,
    color: '#fff',
    display: 'inline-block',
    padding: '40px 40px 5px',
    fontSize: '0.8125rem',
    position: 'absolute',
    top: -24,
    right: -55,
    transform: 'rotate(45deg)'
}));

// Reusable PlanList Component
const PlanList = ({ plan, onStartTrial, priceFlag }) => {
    const theme = useTheme();

    return (
        <Grid item xs={12} sm={3} md={1.71} sx={{ background: theme.palette.text.primary }}>
            <FeatureContentWrapper>
                {plan.popular && <PopularBadgeWrapper>Popular</PopularBadgeWrapper>}
                <Grid container spacing={gridSpacing}>
                    <Grid item xs={12}>
                        <Typography
                            variant="h6"
                            sx={{ fontSize: '1.25rem', fontWeight: 500, position: 'relative', color: theme.palette.secondary.main }}
                        >
                            {plan.title}
                        </Typography>
                    </Grid>
                    <Grid item xs={12}>
                        <Typography
                            variant="body2"
                            sx={{
                                fontSize: '1.5rem',
                                color: theme.palette.secondary.main,
                                fontWeight: 700,
                                '& > span': {
                                    fontSize: '1.25rem',
                                    fontWeight: 500
                                },
                                [theme.breakpoints.down('lg')]: {
                                    fontSize: '1.25rem',
                                    '& > span': {
                                        fontSize: '1rem'
                                    }
                                }
                            }}
                        >
                            <sup>$</sup>
                            {priceFlag === 'yearly' ? plan.price.yearly : plan.price.monthly}
                            <span>/{priceFlag === 'yearly' ? 'Year' : 'Month'}</span>
                        </Typography>
                        <br />
                    </Grid>
                    <Grid item xs={12}>
                        <Button
                            variant={plan.popular ? 'contained' : 'outlined'}
                            sx={{
                                whiteSpace: 'nowrap', // Prevents text wrapping
                                minWidth: '120px', // Ensures minimum width
                                px: 2, // Horizontal padding
                                fontSize: '0.875rem', // Adjust font size if needed
                                fontWeight: 600, // Makes text slightly bolder
                                padding: '8px'
                            }}
                            onClick={() => onStartTrial(plan.priceId, plan.id)}
                            color={plan.popular ? 'secondary' : 'primary'}
                        >
                            Start free trial
                        </Button>
                    </Grid>
                </Grid>
            </FeatureContentWrapper>
        </Grid>
    );
};

PlanList.propTypes = {
    plan: PropTypes.object,
    priceFlag: PropTypes.string
};

// Reusable ListItem Component
const ListItem = ({ item }) => (
    <Grid item xs={4} sm={3} md={1.71}>
        {item === 1 && (
            <Box sx={{ px: 3, py: 1.5 }}>
                <CheckCircleTwoToneIcon sx={{ color: 'success.dark' }} />
            </Box>
        )}
        {item === 0 && (
            <Box sx={{ px: 3, py: 1.5 }}>
                <RemoveRoundedIcon sx={{ opacity: '0.3' }} />
            </Box>
        )}
    </Grid>
);

ListItem.propTypes = {
    item: PropTypes.number
};

// Reusable OrderButton Component
const OrderButton = ({ popular }) => (
    <Grid item xs={12} sm={3} md={1.71} sx={{ padding: '10px' }}>
        <Button
            variant={popular ? 'contained' : 'outlined'}
            sx={{
                whiteSpace: 'nowrap', // Prevents text wrapping
                minWidth: '120px', // Ensures minimum width
                px: 2, // Horizontal padding
                fontSize: '0.875rem', // Adjust font size if needed
                fontWeight: 600, // Makes text slightly bolder
                padding: '8px'
            }}
            color={popular ? 'secondary' : 'primary'}
        >
            Start free trial
        </Button>
    </Grid>
);

OrderButton.propTypes = {
    popular: PropTypes.bool
};

// Generic Pricing Table Component
const PricingTable = ({ plans, onStartTrial, planList, priceFlag, setPriceFlag, showDetails, scroll }) => {
    const theme = useTheme();
    const [expanded, setExpanded] = useState(null);
    const [isSticky, setIsSticky] = useState(false);
    const headerRef = useRef(null);
    const footerRef = useRef(null);
    const appBarHeight = 64; // Height of the AppBar in pixels

    useEffect(() => {
        if (scroll) {
            const handleScroll = () => {
                if (headerRef.current && footerRef.current) {
                    const headerRect = headerRef.current.getBoundingClientRect();
                    const footerRect = footerRef.current.getBoundingClientRect();
                    // Sticky behavior starts when the header's top is less than or equal to the AppBar height
                    // Sticky behavior stops when the footer's top is less than or equal to the AppBar height
                    const shouldSticky = headerRect.top <= appBarHeight && footerRect.top > appBarHeight;
                    setIsSticky(shouldSticky);
                }
            };

            window.addEventListener('scroll', handleScroll);
            return () => window.removeEventListener('scroll', handleScroll);
        }

        // eslint-disable-next-line prettier/prettier
        return () => { };
    }, [scroll]);

    return (
        <Grid container padding={5} spacing={gridSpacing} sx={{ background: theme.palette.text.primary, padding: '50px', border: 'none' }}>
            <Grid item xs={12} style={{ border: 'none' }}>
                <MainCard content={false} sx={{ textAlign: 'center', border: '2px solid #ffffff' }}>
                    {/* Sticky Plan Header */}
                    <Box
                        ref={headerRef} // Attach ref to the sticky header
                        sx={{
                            backgroundColor: theme.palette.text.primary
                        }}
                    >
                        <Grid container spacing={0}>
                            <Grid item xs={12} sm={3} md={1.71}>
                                <FeatureContentWrapper>
                                    <Stack spacing={3} style={{ padding: '40px 0px' }}>
                                        <ButtonGroup variant="contained" fullWidth>
                                            <Button
                                                size="small"
                                                sx={{ bgcolor: priceFlag === 'yearly' ? 'primary.main' : 'primary.200' }}
                                                onClick={() => setPriceFlag('yearly')}
                                            >
                                                Annual
                                            </Button>
                                            <Button
                                                size="small"
                                                sx={{ bgcolor: priceFlag === 'monthly' ? 'primary.main' : 'primary.200' }}
                                                onClick={() => setPriceFlag('monthly')}
                                            >
                                                Monthly
                                            </Button>
                                        </ButtonGroup>
                                        <CurrencyButtonGroup />
                                    </Stack>
                                </FeatureContentWrapper>
                            </Grid>
                            {plans.map((plan, index) => (
                                <PlanList plan={plan} onStartTrial={onStartTrial} priceFlag={priceFlag} key={index} />
                            ))}
                        </Grid>
                    </Box>

                    {/* Rest of the Code (Plan List, Features, etc.) */}
                    {planList.map((list, index) => (
                        <React.Fragment key={index}>
                            {list.type === 'group' && (
                                <FeatureTitleWrapper>
                                    <Typography variant="subtitle1">{list.label}</Typography>
                                </FeatureTitleWrapper>
                            )}
                            {list.type === 'list' && (
                                <Grid
                                    container
                                    spacing={0}
                                    sx={{
                                        borderBottom: '1px solid',
                                        borderColor:
                                            theme.palette.mode === 'dark'
                                                ? `${theme.palette.background.default} !important`
                                                : `${theme.palette.grey[200]} !important`,
                                        backgroundColor: theme.palette.text.primary
                                    }}
                                >
                                    <Grid item xs={12} sm={3} md={1.71} onClick={() => setExpanded(expanded === index ? null : index)}>
                                        <Box sx={{ px: 1, py: 1.5 }}>
                                            <Typography
                                                sx={{
                                                    fontSize: { xs: '2rem', sm: '1rem', md: '1rem' },
                                                    fontWeight: 900,
                                                    lineHeight: 1.4,
                                                    color: theme.palette.text.dark
                                                }}
                                                component="div"
                                                align="left"
                                                variant="body2"
                                            >
                                                {list.label}
                                                {showDetails && (
                                                    <IconButton size="small">
                                                        <ExpandMoreIcon
                                                            sx={{ transform: expanded === index ? 'rotate(180deg)' : 'rotate(0deg)' }}
                                                        />
                                                    </IconButton>
                                                )}
                                            </Typography>
                                        </Box>
                                    </Grid>
                                    {list.permission?.map((item, i) => (
                                        <ListItem key={i} item={item} />
                                    ))}
                                    {showDetails && (
                                        <Collapse in={expanded === index} timeout="auto" unmountOnExit>
                                            <Box
                                                sx={{
                                                    p: 2,
                                                    background: `${theme.palette.background.secondary}!important`,
                                                    color: theme.palette.primary.dark,
                                                    width: '100%',
                                                    borderRadius: '8px'
                                                }}
                                            >
                                                <Typography
                                                    variant="body1"
                                                    sx={{
                                                        fontSize: '1rem',
                                                        lineHeight: 1.6,
                                                        fontWeight: 400,
                                                        transition: 'opacity 0.3s ease',
                                                        textAlign: 'left',
                                                        background: `${theme.palette.background.secondary}!important`,
                                                        color: theme.palette.primary.dark
                                                    }}
                                                >
                                                    {list?.details}
                                                </Typography>
                                            </Box>
                                        </Collapse>
                                    )}
                                </Grid>
                            )}
                        </React.Fragment>
                    ))}
                    <Grid
                        sx={{
                            backgroundColor: theme.palette.text.primary
                        }}
                        container
                        spacing={0}
                        ref={footerRef}
                    >
                        {' '}
                        {/* Attach ref to the footer */}
                        <Grid item xs={12} sm={3} md={1.71} />
                        <OrderButton popular={false} />
                        <OrderButton popular />
                        <OrderButton popular={false} />
                        <OrderButton popular={false} />
                        <OrderButton popular={false} />
                        <OrderButton popular={false} />
                    </Grid>
                </MainCard>
            </Grid>
        </Grid>
    );
};

PricingTable.propTypes = {
    plans: PropTypes.array.isRequired,
    planList: PropTypes.array.isRequired,
    priceFlag: PropTypes.string.isRequired,
    setPriceFlag: PropTypes.func.isRequired,
    showDetails: PropTypes.bool,
    scroll: PropTypes.bool
};

export default PricingTable;
